import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import type {DialogProps} from '../../../hocs/withDialogContainer'
import withDialogContainer from '../../../hocs/withDialogContainer'
import {useBranch} from '../../../hooks/routes'
import {DialogType} from '../../../types'
import type {BranchSelectBranchesQuery} from '../BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'

import type {BuildStatusWidgetQuery} from './__generated__/BuildStatusWidgetQuery.graphql'
import BuildStatusWidget from './BuildStatusWidget'
import {query} from './BuildStatusWidget.queries'
import type {
  BuildStatusWidgetBaseProps,
  BuildStatusWidgetContainerProps,
} from './BuildStatusWidget.types'

export const DIALOG_TYPE = DialogType.BUILD_STATUS_WIDGET
const BuildStatusWidgetContainer = withDialogContainer<BuildStatusWidgetContainerProps>(
  DIALOG_TYPE,
  (state, props) => props.buildTypeId,
)(({
  overrideCloseDialog,
  closeDialog,
  initiallySelectedBranch,
  mainQuery,
  ...restProps
}: DialogProps<BuildStatusWidgetContainerProps>) => {
  const {buildType} = usePreloadedQuery(query, mainQuery)
  const isExternalStatusAllowed = buildType?.externalStatusAllowed
  const hookBranch = useBranch()
  return restProps.isOpened ? (
    <BuildStatusWidget
      initiallySelectedBranch={initiallySelectedBranch ?? hookBranch}
      closeDialog={overrideCloseDialog ?? closeDialog}
      isExternalStatusAllowed={isExternalStatusAllowed}
      {...restProps}
    />
  ) : null
})

type Queries = {main: BuildStatusWidgetQuery; branches: BranchSelectBranchesQuery}

export default function BuildStatusWidgetContainerWrapper({
  queries,
  props,
}: EntryPointProps<Queries, {}, BuildStatusWidgetBaseProps, {}>) {
  return (
    <BuildStatusWidgetContainer
      {...props}
      mainQuery={queries.main}
      branchesQueryRef={queries.branches}
    />
  )
}

export type BuildStatusWidgetComponent = typeof BuildStatusWidgetContainerWrapper
