import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import {Header, Content} from '@jetbrains/ring-ui-built/components/island/island'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import {baseUri} from '@jetbrains/teamcity-ui'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import * as React from 'react'
import {Suspense} from 'react'

import {Policy} from '../../../rest/branches'
import {stringifyId} from '../../../types'
import {copyClipboard} from '../../../utils/clipboard'
import {cmdOrCtrlPlus} from '../../../utils/keys'
import {resolveHelpURL} from '../../../utils/url'
import BranchSelectContainer from '../BranchSelect/BranchSelect.container'
import HelpLink from '../HelpLink/HelpLink'
import Icon from '../Icon/Icon'

import type {BuildStatusWidgetOwnProps} from './BuildStatusWidget.types'

import styles from './BuildStatusWidget.module.css'

const formats = ['link', 'markdown', 'HTML']
const altText = 'TeamCity build status'
const messageTimeout = 2000 // ms

const capitalize = (str: string) => str[0].toUpperCase() + str.substring(1)

function dataToCopy(format: string, imageSrc: string): string {
  switch (format) {
    case 'link':
      return imageSrc

    case 'markdown':
      return `![${altText}](${imageSrc})`

    case 'HTML':
      return `<img src="${imageSrc}" alt="${altText}">`

    default:
      return ''
  }
}

type FormatButtonProps = {
  format: string
  setFormat: (arg0: string) => void
  active: boolean
}

function FormatButton({format, setFormat, active}: FormatButtonProps) {
  const handleClick = React.useCallback(() => setFormat(format), [format, setFormat])
  return (
    <Button active={active} onClick={handleClick}>
      {capitalize(format)}
    </Button>
  )
}

function BuildStatusWidget({
  buildTypeId,
  buildTypeInternalId,
  initiallySelectedBranch,
  closeDialog,
  withPreview = true,
  isExternalStatusAllowed,
  branchesQueryRef,
}: BuildStatusWidgetOwnProps) {
  const [selectedFormat, setFormat] = React.useState('link')
  const [selectedBranch, setBranch] = React.useState(initiallySelectedBranch)
  const projectOrBuildTypeNode = React.useMemo(
    () =>
      ({
        nodeType: 'bt',
        id: buildTypeId,
      }) as const,
    [buildTypeId],
  )
  let locator = `buildType:id:${stringifyId(buildTypeId)}`

  if (selectedBranch?.name != null && selectedBranch.default !== true) {
    locator += `,branch:name:${encodeURIComponent(selectedBranch.name)}`
  }

  const imageSrc = `${baseUri}/app/rest/builds/${locator}/statusIcon.svg`
  const data = dataToCopy(selectedFormat, imageSrc)
  const textFieldRef = React.useRef<HTMLTextAreaElement>(null)
  const selectData = React.useCallback(() => textFieldRef.current?.select(), [])
  const copyData = React.useCallback(async () => {
    try {
      await copyClipboard(data)
      alert.message(`${capitalize(selectedFormat)} has been copied`, messageTimeout)
    } catch {
      selectData()
      alert.message(`Press ${cmdOrCtrlPlus}C to copy ${selectedFormat}`, messageTimeout)
    }
  }, [data, selectData, selectedFormat])
  return (
    <Dialog label="Status Icon" show onCloseAttempt={closeDialog} showCloseButton closeButtonInside>
      <Header>{'Status Icon'}</Header>
      <Content>
        <div className={styles.description}>
          {'An SVG icon that represents the status of the last build. Please refer to the '}
          <HelpLink
            Component={Link}
            url={resolveHelpURL('rest-api-reference.html#Build+Status+Icon')}
            preservePlus
          >
            {'documentation'}
          </HelpLink>
          {' for more supported requests.'}
        </div>
        {branchesQueryRef && (
          <Suspense>
            <BranchSelectContainer
              className={styles.branchSelect}
              onSelect={setBranch}
              selected={selectedBranch}
              buildTypeInternalId={buildTypeInternalId}
              projectOrBuildTypeNode={projectOrBuildTypeNode}
              policy={Policy.ALL_BRANCHES}
              excludeWildcard
              branchesQueryRef={branchesQueryRef}
            />
          </Suspense>
        )}
        {withPreview && (
          <div className={styles.preview}>
            <Text info className={styles.caption}>
              {'Preview'}
            </Text>
            <img src={imageSrc} alt={altText} className={styles.icon} />
          </div>
        )}
        <div className={styles.formatSelect}>
          <Text info className={styles.caption}>
            {'Format'}
          </Text>
          <ButtonGroup>
            {formats.map(format => (
              <FormatButton
                key={format}
                format={format}
                setFormat={setFormat}
                active={format === selectedFormat}
              />
            ))}
          </ButtonGroup>
        </div>
        <Input
          key={selectedFormat}
          inputRef={textFieldRef}
          multiline
          className={styles.data}
          label={capitalize(selectedFormat)}
          value={data}
          onFocus={selectData}
        />
        {isExternalStatusAllowed === false && (
          <span className={styles.warning}>
            <Icon name="warning" className={styles.warningIcon} />
            {
              '“Enable status widget” option for this build configuration is OFF, so only authorized users will see this icon.'
            }
            <HelpLink
              className={styles.helpLink}
              url={resolveHelpURL('configuring-general-settings.html#Enable+Status+Widget')}
              Component={IconButton}
              icon="help"
              preservePlus
            />
          </span>
        )}
      </Content>
      <Panel>
        <Button onClick={copyData} primary>{`Copy ${selectedFormat}`}</Button>
        <Button onClick={closeDialog}>{'Close'}</Button>
      </Panel>
    </Dialog>
  )
}

export default BuildStatusWidget
